select.where:
del_flag ='0'
and id != #{id}
and machine_code = #{machineCode}
and machine_name = #{machineName}

mapper.update:
update t_tq_machine_info
machine_name = #{machineName,jdbcType=VARCHAR}, efficiency = #{efficiency,jdbcType=DOUBLE}, tooling_info = #{toolingInfo,jdbcType=VARCHAR}, quata = #{quata,jdbcType=DECIMAL}, class_shift = #{classShift,jdbcType=VARCHAR}, open_machine_class = #{openMachineClass,jdbcType=VARCHAR}, status = #{status,jdbcType=VARCHAR}, remark = #{remark,jdbcType=VARCHAR}, del_flag = #{delFlag,jdbcType=VARCHAR}, create_by = #{createBy,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=DATE}, update_by = #{updateBy,jdbcType=VARCHAR}, update_time = #{updateTime,jdbcType=DATE},
where id = #{id}

merge into t_tq_machine_info a USING (
select #{MACHINE.machineCode,jdbcType=VARCHAR} machine_code, #{MACHINE.machineName,jdbcType=VARCHAR} machine_name, #{MACHINE.efficiency,jdbcType=DOUBLE} efficiency, #{MACHINE.toolingInfo,jdbcType=VARCHAR} tooling_info, #{MACHINE.quata,jdbcType=DOUBLE} quata, #{MACHINE.classShift,jdbcType=VARCHAR} class_shift, #{MACHINE.openMachineClass,jdbcType=VARCHAR} open_machine_class, #{MACHINE.status,jdbcType=VARCHAR} status, #{MACHINE.createBy,jdbcType=VARCHAR} create_by, #{MACHINE.createTime,jdbcType=DATE} create_time, #{MACHINE.updateBy,jdbcType=VARCHAR} update_by, #{MACHINE.updateTime,jdbcType=DATE} update_time, #{MACHINE.remark,jdbcType=VARCHAR} remark from dual
) b ON (a.machine_code = b.machine_code and a.del_flag = '0') WHEN MATCHED THEN UPDATE SET a.machine_name = b.machine_name, a.efficiency = b.efficiency, a.tooling_info = b.tooling_info, a.quata = b.quata, a.class_shift = b.class_shift, a.open_machine_class = b.open_machine_class, a.status = b.status, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.machine_code, a.machine_name, a.efficiency , a.tooling_info , a.quata , a.class_shift , a.open_machine_class , a.status , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.machine_code, b.machine_name, b.efficiency, b.tooling_info, b.quata, b.class_shift, b.open_machine_class, b.status, b.create_by, sysdate, b.remark, '0' )
